def _parse_version(version):
    """Return the parts of a version string that affect its order."""
    without_build = version.split("+", 1)[0]

    if "-" in without_build:
        main_part, pre_part = without_build.split("-", 1)
        prerelease = pre_part.split(".")
    else:
        main_part = without_build
        prerelease = None

    major, minor, patch = (int(part) for part in main_part.split("."))
    return major, minor, patch, prerelease


def _identifier_key(identifier):
    """Numeric identifiers sort below alphanumeric ones."""
    if identifier.isdigit():
        return (0, int(identifier))
    return (1, identifier)


def _sort_key(version):
    major, minor, patch, prerelease = _parse_version(version)

    if prerelease is None:
        # A version without a pre-release is higher than one with it.
        return (major, minor, patch, 1, ())

    return (
        major,
        minor,
        patch,
        0,
        tuple(_identifier_key(part) for part in prerelease),
    )


def sort_versions(vs):
    """Sort semantic version strings by SemVer 2.0.0 precedence, lowest first."""
    return sorted(vs, key=_sort_key)
